from collections import Counter
def f(g):
    g=[r[:] for r in g]; h=len(g); w=len(g[0])
    vals=Counter(v for r in g for v in r).most_common()
    base=vals[0][0]
    out=[]
    for i,r in enumerate(g):
        row=[]
        for j,v in enumerate(r):
            if v==7: row.append(7)
            elif v==base and any(0<=i+di<h and 0<=j+dj<w and g[i+di][j+dj]==7 for di in(-1,0,1) for dj in(-1,0,1)): row.append(1)
            else: row.append(base)
        out.append(row)
    return out
